const express = require('express');
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');
const sharp = require('sharp');

const app = express();
const UPLOAD_DIR = '/var/app/uploads';
const PROCESSED_DIR = '/var/app/processed';
const SERVICE_SECRET = process.env.SERVICE_SECRET;
if (!SERVICE_SECRET) {
  console.error('SERVICE_SECRET environment variable is required');
  process.exit(1);
}

// Cross-service auth middleware
function verifyServiceToken(req, res, next) {
  const token = req.headers['x-service-token'];
  if (!token) return res.status(401).json({ error: 'Missing service token' });
  const parts = token.split('.');
  if (parts.length !== 2) return res.status(401).json({ error: 'Invalid token format' });
  const [payload, signature] = parts;
  const expectedSig = crypto.createHmac('sha256', SERVICE_SECRET)
    .update(payload).digest('hex');
  try {
    const sigBuf = Buffer.from(signature, 'hex');
    const expBuf = Buffer.from(expectedSig, 'hex');
    // Guard against length mismatch which would throw in timingSafeEqual
    if (sigBuf.length !== expBuf.length || !crypto.timingSafeEqual(sigBuf, expBuf)) {
      return res.status(401).json({ error: 'Invalid signature' });
    }
    const decoded = JSON.parse(Buffer.from(payload, 'base64').toString());
    if (decoded.exp && decoded.exp < Date.now()) {
      return res.status(401).json({ error: 'Token expired' });
    }
    req.serviceIdentity = decoded;
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

// Normalize path for safe directory resolution
function resolveImagePath(baseDir, requestedPath) {
  const normalized = path.normalize(requestedPath);
  const resolved = path.resolve(baseDir, normalized);
  // Security check: ensure resolved path starts with base directory
  if (!resolved.startsWith(baseDir + path.sep) && resolved !== baseDir) {
    return null;
  }
  return resolved;
}

// List processed images for a given job
app.get('/api/v1/jobs/:jobId/images', verifyServiceToken, (req, res) => {
  const jobId = req.params.jobId;
  // Validate jobId format
  if (!/^[a-f0-9\-]{36}$/.test(jobId)) {
    return res.status(400).json({ error: 'Invalid job ID format' });
  }
  const jobDir = resolveImagePath(PROCESSED_DIR, jobId);
  if (!jobDir) return res.status(403).json({ error: 'Access denied' });
  if (!fs.existsSync(jobDir)) return res.status(404).json({ error: 'Job not found' });
  const files = fs.readdirSync(jobDir);
  res.json({ jobId, images: files });
});

// Serve a specific processed image
app.get('/api/v1/images/:imagePath(*)', verifyServiceToken, (req, res) => {
  const imagePath = req.params.imagePath;
  const resolved = resolveImagePath(PROCESSED_DIR, imagePath);
  if (!resolved) return res.status(403).json({ error: 'Access denied' });
  if (!fs.existsSync(resolved)) return res.status(404).json({ error: 'Not found' });
  const stat = fs.statSync(resolved);
  if (stat.isDirectory()) {
    return res.status(403).json({ error: 'Directory listing not permitted' });
  }
  const allowedExt = ['.webp', '.png', '.jpg', '.jpeg'];
  if (!allowedExt.includes(path.extname(resolved).toLowerCase())) {
    return res.status(403).json({ error: 'File type not allowed' });
  }
  res.sendFile(resolved);
});

// Process and resize uploaded image
app.post('/api/v1/process', verifyServiceToken, express.raw({ type: 'image/*', limit: '10mb' }), async (req, res) => {
  const jobId = crypto.randomUUID();
  const outputDir = path.join(PROCESSED_DIR, jobId);
  fs.mkdirSync(outputDir, { recursive: true });
  const sizes = [{ name: 'thumb', w: 150, h: 150 }, { name: 'medium', w: 800, h: 600 }, { name: 'large', w: 1920, h: 1080 }];
  try {
    for (const size of sizes) {
      await sharp(req.body).resize(size.w, size.h, { fit: 'inside' }).toFile(path.join(outputDir, `${size.name}.webp`));
    }
    res.json({ jobId, status: 'completed', images: sizes.map(s => `${s.name}.webp`) });
  } catch (err) {
    res.status(500).json({ error: 'Processing failed' });
  }
});

// Health check endpoint (no auth required)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: Date.now() });
});

app.listen(3000, () => console.log('Image service running on :3000'));
